01d7e1974111021bcaaf731b188e5","initially_deferred":false},{"name":"aaa_application_dml_admission_statement","table":"track_b_team_rollback_intents","enabled":"O","internal":false,"deferrable":false,"definition_md5":"10b415aa3259b3f046f402afe952c62f","initially_deferred":false},{"name":"aaa_application_dml_admission_row","table":"track_b_team_rollbacks","enabled":"O","internal":false,"deferrable":false,"definition_md5":"074f55b02a6add0e0257f5905603f19e","initially_deferred":false},{"name":"aaa_application_dml_admission_statement","table":"track_b_team_rollbacks","enabled":"O","internal":false,"deferrable":false,"definition_md5":"da9b7f874335e8c470f1ab1e542013b0","initially_deferred":false},{"name":"aaa_application_dml_admission_row","table":"workload_issues","enabled":"O","internal":false,"deferrable":false,"definition_md5":"726057edc627bd3fa7559ea15f878188","initially_deferred":false},{"name":"aaa_application_dml_admission_statement","table":"workload_issues","enabled":"O","internal":false,"deferrable":false,"definition_md5":"d18dbfe318ee6bacc237feb3468387b4","initially_deferred":false},{"name":"aaa_application_dml_admission_row","table":"workload_plan","enabled":"O","internal":false,"deferrable":false,"definition_md5":"588eee08f983356afde7e00303fecbd0","initially_deferred":false},{"name":"aaa_application_dml_admission_statement","table":"workload_plan","enabled":"O","internal":false,"deferrable":false,"definition_md5":"7367fd5d1dfcdee09b1b5728f42151db","initially_deferred":false}]}$expected$::jsonb; item jsonb; actual jsonb;
begin
 for item in select to_jsonb(name) from unnest(array['card_write_transaction_context_v1','card_write_admission_v1','syncview_retirement_admission','production_native_ordinary_receipt_admissions']) name loop
  if not exists(select from pg_class c where c.oid=to_regclass('public.'||(item#>>'{}')) and c.relrowsecurity and pg_get_userbyid(c.relowner)='postgres' and not has_table_privilege('service_role',c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') and not has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') and not has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) then raise exception 'retirement_private_control_acl:%',item#>>'{}';end if;
 end loop;
 for item in select value from jsonb_array_elements(expected->'functions') loop
  select jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'kind',p.prokind,'language',l.lanname,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'body_raw_md5',md5(p.prosrc),'volatility',p.provolatile,'security_definer',p.prosecdef,'strict',p.proisstrict,'leakproof',p.proleakproof,'parallel',p.proparallel,'config',p.proconfig,'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE'),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE')) into actual from pg_proc p join pg_language l on l.oid=p.prolang where p.pronamespace='public'::regnamespace and p.proname=item->>'name' and pg_get_function_identity_arguments(p.oid)=item->>'arguments';
  if actual is distinct from item then raise exception 'retirement_dependency_contract:%',item->>'name';end if;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'table',c.relname,'enabled',t.tgenabled,'internal',t.tgisinternal,'deferrable',t.tgdeferrable,'definition_md5',md5(pg_get_triggerdef(t.oid)),'initially_deferred',t.tginitdeferred) order by c.relname,t.tgname),'[]'::jsonb) into actual from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relnamespace='public'::regnamespace and not t.tgisinternal and (c.relname in ('mirror_outbox','production_native_ordinary_receipt_admissions','production_intake_manifests','production_label_catalog_versions','syncview_retirement_admission','card_write_transaction_context_v1') or t.tgname like 'aaa_application_dml_admission_%');
 if actual is distinct from expected->'triggers' then raise exception 'retirement_trigger_contract';end if;

 if not exists(select from pg_trigger t join pg_proc p on p.oid=t.tgfoid where t.tgrelid='linear_exit_provider.send_attempts_v1'::regclass and t.tgname='retirement_send_fence_v1' and t.tgenabled='A' and not t.tgisinternal and p.pronamespace='linear_exit_provider'::regnamespace and p.proname='retirement_send_fence_v1' and md5(p.prosrc)='575f10ca7b9865005d9666393628c395' and p.prosecdef and p.proconfig=array['search_path=pg_catalog, public'] and pg_get_userbyid(p.proowner)='postgres' and not has_function_privilege('service_role',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE') and t.tgtype=7 and t.tgnargs=0 and t.tgqual is null) then raise exception 'retirement_provider_fence_missing';end if;
end $contract$;
revoke all on function public.production_retirement_contract_assert_v1() from public,anon,authenticated,service_role;

create function public.production_retirement_capabilities_v1(p_expected jsonb) returns jsonb
language plpgsql security definer set search_path=pg_catalog,public as $cap$
declare flags jsonb; epochs jsonb; label_cap jsonb; team text;
begin
 perform 1 from public.syncview_runtime_flags where key in ('prod_authority','linear_outbound_enabled','linear_legacy_parity_enabled','native_intake_epochs','native_assignment_epochs','production_native_label_catalog','production_native_ordinary_receipts') order by key for share;
 select jsonb_object_agg(key,value) into flags from public.syncview_runtime_flags where key in ('prod_authority','linear_outbound_enabled','linear_legacy_parity_enabled','native_intake_epochs','native_assignment_epochs','production_native_label_catalog','production_native_ordinary_receipts');
 if jsonb_typeof(p_expected) is distinct from 'object' or flags is distinct from p_expected then raise exception 'retirement_capability_cas';end if;
 if flags->'prod_authority' is distinct from '{"video":"syncview","graphics":"syncview"}'::jsonb or flags->'linear_outbound_enabled' is distinct from '{"mode":"off"}'::jsonb or flags->'linear_legacy_parity_enabled' is distinct from '{"enabled":false}'::jsonb then raise exception 'retirement_provider_stops_required';end if;
 epochs:=public.production_native_intake_epochs();label_cap:=public.production_label_catalog_capability();
 if label_cap->>'mode' is distinct from 'native' then raise exception 'retirement_native_labels_required';end if;
 foreach team in array array['video','graphics'] loop
  if nullif(epochs->>team,'') is null or nullif(public.production_assignment_epoch(team),'') is null or public.production_native_ordinary_capability(team)->>'mode' is distinct from 'native' then raise exception 'retirement_native_epochs_required';end if;
  perform public.production_label_catalog_read_attested((label_cap->>'version_id')::uuid,team);
 end loop;
 return flags;
end $cap$;
revoke all on function public.production_retirement_capabilities_v1(jsonb) from public,anon,authenticated,service_role;

create function public.production_retirement_drain_assert_v1() returns void
language plpgsql security definer set search_path=pg_catalog,public as $drain$
begin
 if exists(select from public.card_write_transaction_context_v1) then raise exception 'retirement_transaction_context_active';end if;
 if exists(select from public.card_write_followups_v1 where state not in ('completed','dispositioned') or outcome is null) then raise exception 'retirement_followup_debt';end if;
 if exists(select from linear_exit_provider.send_attempts_v1 where state is distinct from 'completed') then raise exception 'retirement_provider_attempt_debt';end if;
 if exists(select from public.mirror_outbox o where o.lock_token is not null or o.locked_at is not null or not(coalesce(public.production_syncview_retirement_typed_native_receipt(o),false) or coalesce(public.production_provider_terminal_eligible_v1(o),false))) then raise exception 'retirement_unresolved_outbox';end if;
 if exists(select from pg_trigger where tgname='linear_exit_maintenance_dml_v1' and not tgisinternal) then raise exception 'retirement_installation_maintenance_active';end if;
end $drain$;
revoke all on function public.production_retirement_drain_assert_v1() from public,anon,authenticated,service_role;

create function public.production_syncview_retirement_activate_v2(p_epoch uuid,p_expected_capabilities jsonb,p_evidence_sha256 text,p_actor text)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $activate$
declare gate public.card_write_admission_v1%rowtype; prior public.syncview_retirement_admission%rowtype; after_row jsonb; receipt jsonb; prior_receipt jsonb; high_id bigint; high_time timestamptz;
begin
 if p_epoch is null or p_evidence_sha256 is null or p_evidence_sha256 !~ '^[0-9a-f]{64}$' or p_actor is null or p_actor<>btrim(p_actor) or length(p_actor) not between 1 and 128 then raise exception 'retirement_switch_request';end if;
 select * into strict gate from public.card_write_admission_v1 where singleton for update;
 if gate.epoch is distinct from p_epoch or gate.mode is distinct from 'closed' then raise exception 'retirement_switch_closed_epoch_required';end if;
 lock table public.mirror_outbox in share row exclusive mode;
 select * into strict prior from public.syncview_retirement_admission where singleton for update;
 perform public.production_retirement_contract_assert_v1();
 perform public.production_retirement_capabilities_v1(p_expected_capabilities);
 perform public.production_retirement_drain_assert_v1();
 select value into prior_receipt from jsonb_array_elements(gate.control_history) with ordinality where value->>'action'='retirement_switch' order by ordinality desc limit 1;
 if prior.mode='retired' then
  if prior_receipt is null or prior_receipt->>'epoch' is distinct from p_epoch::text or prior_receipt->>'evidence_sha256' is distinct from p_evidence_sha256 or prior_receipt->>'actor' is distinct from p_actor or prior_receipt->'capabilities' is distinct from p_expected_capabilities or prior_receipt->'retirement' is distinct from to_jsonb(prior) then raise exception 'retirement_switch_replay_binding';end if;
  return prior_receipt;
 end if;
 if prior_receipt is not null then raise exception 'retirement_switch_history_conflict';end if;
 select coalesce(max(id),0),coalesce(max(created_at),clock_timestamp()) into high_id,high_time from public.mirror_outbox;
 after_row:=to_jsonb(prior)||jsonb_build_object('mode','retired','activated_at',clock_timestamp(),'activated_reason','reviewed-evidence-sha256:'||p_evidence_sha256,'high_water_outbox_id',high_id,'high_water_created_at',high_time);
 insert into public.card_write_transaction_context_v1(transaction_id,backend_pid,epoch,kind,scope) values(txid_current(),pg_backend_pid(),gate.epoch,'retirement_switch',jsonb_build_object('before',to_jsonb(prior),'after',after_row));
 update public.syncview_retirement_admission set mode='retired',activated_at=(after_row->>'activated_at')::timestamptz,activated_reason=after_row->>'activated_reason',high_water_outbox_id=high_id,high_water_created_at=high_time where singleton;
 delete from public.card_write_transaction_context_v1 where transaction_id=txid_current();
 receipt:=jsonb_build_object('action','retirement_switch','epoch',p_epoch,'evidence_sha256',p_evidence_sha256,'actor',p_actor,'capabilities',p_expected_capabilities,'retirement',after_row,'application_gate','closed','external_evidence_truth_verified',false);
 update public.card_write_admission_v1 set control_history=control_history||jsonb_build_array(receipt) where singleton;
 return receipt;
end $activate$;
revoke all on function public.production_syncview_retirement_activate_v2(uuid,jsonb,text,text) from public,anon,authenticated;
grant execute on function public.production_syncview_retirement_activate_v2(uuid,jsonb,text,text) to service_role;

-- Separate operator step after custody review; the old reopen RPC still refuses retired mode.
create function public.production_syncview_retirement_native_reopen_v1(p_epoch uuid,p_switch_receipt jsonb,p_evidence_sha256 text,p_actor text)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $reopen$
declare gate public.card_write_admission_v1%rowtype; retirement public.syncview_retirement_admission%rowtype; prior_receipt jsonb; prior_reopen jsonb; next_epoch uuid:=gen_random_uuid(); result jsonb;
begin
 if p_epoch is null or p_evidence_sha256 is null or p_evidence_sha256 !~ '^[0-9a-f]{64}$' or p_actor is null or p_actor<>btrim(p_actor) or length(p_actor) not between 1 and 128 then raise exception 'retirement_native_reopen_request';end if;
 select * into strict gate from public.card_write_admission_v1 where singleton for update;
 select value into prior_reopen from jsonb_array_elements(gate.control_history) with ordinality where value->>'action'='retirement_native_reopen' order by ordinality desc limit 1;
 if gate.mode='open' and prior_reopen is not null then
  select * into strict retirement from public.syncview_retirement_admission where singleton for share;
  select value into prior_receipt from jsonb_array_elements(gate.control_history) with ordinality where value->>'action'='retirement_switch' order by ordinality desc limit 1;
  if prior_reopen->>'epoch' is distinct from gate.epoch::text or prior_reopen->>'prior_epoch' is distinct from p_epoch::text or prior_reopen->>'evidence_sha256' is distinct from p_evidence_sha256 or prior_reopen->>'actor' is distinct from p_actor or prior_receipt is distinct from p_switch_receipt or prior_receipt->'retirement' is distinct from to_jsonb(retirement) then raise exception 'retirement_native_reopen_replay_binding';end if;
  return prior_reopen;
 end if;
 if gate.epoch is distinct from p_epoch or gate.mode is distinct from 'closed' then raise exception 'retirement_native_reopen_cas';end if;
 lock table public.mirror_outbox in share row exclusive mode;
 select * into strict retirement from public.syncview_retirement_admission where singleton for share;
 select value into prior_receipt from jsonb_array_elements(gate.control_history) with ordinality where value->>'action'='retirement_switch' order by ordinality desc limit 1;
 if retirement.mode is distinct from 'retired' or prior_receipt is null or prior_receipt is distinct from p_switch_receipt or prior_receipt->>'epoch' is distinct from p_epoch::text or prior_receipt->'retirement' is distinct from to_jsonb(retirement) then raise exception 'retirement_native_reopen_receipt';end if;
 perform public.production_retirement_contract_assert_v1();perform public.production_retirement_capabilities_v1(prior_receipt->'capabilities');perform public.production_retirement_drain_assert_v1();
 result:=jsonb_build_object('action','retirement_native_reopen','prior_epoch',p_epoch,'epoch',next_epoch,'evidence_sha256',p_evidence_sha256,'actor',p_actor,'external_evidence_truth_verified',false);
 update public.card_write_admission_v1 set epoch=next_epoch,mode='open',closed_at=null,sealed_at=null,reason='retired native writes reviewed',control_history=control_history||jsonb_build_array(result) where singleton;
 return result;
end $reopen$;
revoke all on function public.production_syncview_retirement_native_reopen_v1(uuid,jsonb,text,text) from public,anon,authenticated;
grant execute on function public.production_syncview_retirement_native_reopen_v1(uuid,jsonb,text,text) to service_role;
commit;
